-- Original: server/internal/quest/upstream/projecteq/growthplane/Tunarean_Earthmelder.lua (sha256 b8f5fe26481f9ae51012ec1b3269a4e25a31964f28f01951460a176831bfb036)
-- P99 Growth quests with IdleQuest faction convenience; eligibility is checked before consuming items.
-- Quest faction requirements are intentionally bypassed. Race/class/deity equipment restrictions do not become invented hand-in gates.
-- Only quest hand-ins and existing ambient hooks are restored here; scripted Tunare raid behavior is a separate runtime boundary.
local item_lib = require("items")

function event_say(e)
  if e.message:findi("hail") and e.other:GetLevel() >= 46 then
    e.self:Say("Hail, my friend. Unfortunately I cannot talk right now. The giants must be dealt with.")
  elseif e.message:findi("giants") and e.other:GetLevel() >= 46 then
    e.self:Say("The giants are continuing to put forth efforts to encroach the lands blessed by Tunare. We need an outrider or preserver to aid us in our continued fight.")
  elseif e.message:findi("preserver") and e.other:GetLevel() >= 46 then
    e.self:Say("Noble preserver, you will be needed to combat the priests of the warbringer. Scouts have reported three priests wandering the Wakening Lands in search of a site to build a shrine to their god. Seek them out, kill them, and bring their heads and those of anyone else involved.")
  elseif e.message:findi("outrider") and e.other:GetLevel() >= 46 then
    e.self:Say("We have need of you to disrupt the construction efforts of the giants in the Wakening Land. Find the frost giant overseer, kill him and any others that are responsible for the building and bring back their heads.")
  end
end

function event_trade(e)
  if e.other:GetLevel() >= 46 and item_lib.check_turn_in(e.trade, { item1 = 31424, item2 = 31425, item3 = 31426, item4 = 31423 }) then
    e.self:Say("May Tunare's blessing be upon thee! Here, take this item and use it wisely.")
    e.other:SummonItem(1208)
    e.other:AddEXP(2500)
  elseif e.other:GetLevel() >= 46 and item_lib.check_turn_in(e.trade, { item1 = 31419, item2 = 31420, item3 = 31421, item4 = 31422 }) then
    e.self:Say("May Tunare's blessing be upon thee! Here, take this item and use it wisely.")
    e.other:SummonItem(1207)
    e.other:AddEXP(2500)
  end
  -- Return unrelated and surplus offers on both accepted and rejected trades.
  item_lib.return_items(e.self, e.other, e.trade)
end

function event_spawn(e)
	eq.set_timer("hum",90000);
end

function event_timer(e)
	e.self:Emote("seems to pulse as its roots dig into the ground around it.");
end

function event_signal(e)
	entity_list = eq.get_entity_list();

	if(e.signal == 1) then
		local mobtypeID =  entity_list:GetMobByNpcTypeID(127098);
		local follow_mob = mobtypeID:GetID();
		eq.follow(follow_mob);
	elseif(e.signal == 2) then
		eq.stop_follow();
	end
end
